      "queryLines": [
        "SELECT sum(net_tuition) net_tuition, sum(tuition_charged) gross_tuition, sum(aid_awarded) total_aid, round(sum(aid_awarded)/sum(tuition_charged)*100,1) discount_rate FROM __CATALOG__.gold.finance_accounts"
      ]
    },
    {
      "name": "netcollege",
