        "SELECT college, 'Applied' stage, applied AS value FROM __CATALOG__.gold.fin_enrollment_funnel UNION ALL SELECT college,'Admitted',admitted FROM __CATALOG__.gold.fin_enrollment_funnel UNION ALL SELECT college,'Enrolled',enrolled FROM __CATALOG__.gold.fin_enrollment_funnel"
      ]
    },
    {
      "name": "aidpct",
      "displayName": "Aid % by college",
      "queryLines": [
        "SELECT college, round(sum(aid_awarded)/sum(tuition_charged)*100,1) aid_pct FROM __CATALOG__.gold.finance_accounts GROUP BY college"
